def createViewCanvasComponents(viewCanvas, config, zIndex=0, sClass=''):
	"""Creates a view canvas component with specified configuration.
	
	Args:
		viewCanvas (dict): Dictionary containing the position and size of the view canvas.
		config (dict): Configuration parameters for the view component.
		zIndex (int, optional): The z-index for layering the view component. Default is 0.
		sClass (str, optional): Additional CSS classes for styling. Default is an empty string.
	
	Returns:
		dict: A dictionary representing the view canvas component with its properties.
	"""

	view={
	  "position": "fixed",
	  "top": '{}px'.format(viewCanvas['top']),
	  "left": '{}px'.format(viewCanvas['left']),
	  "bottom": "auto",
	  "right": "auto",
	  "zIndex": zIndex,
	  "width": '{}px'.format(viewCanvas['width']),
	  "height": '{}px'.format(viewCanvas['height']),
	  "viewPath": "Exchange/ArchitectureBuilder/Frames/DragFrame",
	  "viewParams": {
	    "params": config,
	    "selected": False,
	    "viewPath": viewCanvas['primaryViewPath']
	  },
	  "style": {
	    "classes": sClass
	  }
	}
	return view
	
